 "content": "def transform(grid):
    """Erase the row containing the longest horizontal run of a non-background color."""
    from collections import Counter

    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    best_len = 0
    best_row = None
    for r, row in enumerate(grid):
        run_len = 0
        run_color = None
        for cell in row:
            if cell != background and cell == run_color:
                run_len += 1
            elif cell != background:
                run_color = cell
                run_len = 1
            else:
                run_color = None
                run_len = 0
            if run_len > best_len:
                best_len = run_len
                best_row = r
    out = [row[:] for row in grid]
    if best_row is not None:
        out[best_row] = [background] * len(out[best_row])
